import { Router } from "express";
import { createAppointment, cancelPendingAppointment, getCustomerDashboard, getMyAppointments, } from "../controllers/appointment.controller.js";
import { authenticate, authorizeCustomer, } from "../middlewares/auth.middleware.js";
const router = Router();
router.use(authenticate, authorizeCustomer);
router.post("/", createAppointment);
router.get("/my-appointments", getMyAppointments);
router.get("/dashboard", getCustomerDashboard);
router.patch("/:id/cancel", cancelPendingAppointment);
export default router;
